<?php require __DIR__.'/../_init.php'; checkCsrf(); $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT); if (!$id) { http_response_code(400); exit('Invalid ID'); } try { $s=$pdo->prepare('DELETE FROM categories WHERE id=?'); $s->execute([$id]); message('Deleted successfully.','index.php'); } catch(PDOException $ex) { message('This item is referenced by order history and cannot be deleted. Set its stock to zero instead.','index.php'); }